Method.Implementation:
	#dim tSC As %Status=$$$OK
	#dim tRTs As %ListOfObjects
	#dim snap As EnsLib.SQL.Snapshot

	if (pRequest.ProcName = "")
	{
		set tSC = $$$ERROR( "Stored procedure name is missing ")
		return tSC
	}
	Set snap=##class(EnsLib.SQL.Snapshot).%New()
	Set snap.MaxRowsToGet=-1
	Set tRTs=##class(%Library.ListOfObjects).%New()
	Set tOutParms=##class(%Library.ListOfObjects).%New()
	Do tRTs.Insert(snap)

	$$$TRACE("Inside "_..%ConfigName_" to call " _ pRequest.ProcName)
	set pResponse = ##class(IHC.ITF.ITFCOMMON.DataStructure.TouchWorksResponse).%New()

	set tSC=..Adapter.SetAutoCommit(1) 

	Do ##class(IHC.ITF.ITFCOMMON.TouchWorksStoredProcUtil).CreateSqlParams(pRequest, .valueArr, .tQuery, .pIOStr)


	try{	
 	   set tSC=..Adapter.ExecuteProcedureParmArray(.tRTs,.tOutParms,tQuery,pIOStr,.valueArr) 	
 	   $$$TRACE("  Status : "_tSC _ ", valueArr:" _valueArr)		 	   	
	}CATCH err {		
	    $$$LOGERROR( "Error while calling stored procedure "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	    set tSC = $$$ERROR( "SQLError:Error while calling stored procedure "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	}	


	if ($$$ISOK(tSC))
	{
		$$$TRACE("OutParam count:" _ tOutParms.Count() )
		set pResponse.outList = ##class(%ListOfDataTypes).%New()
	    set pResponse.RETURNVALUE = tOutParms.GetAt(1)
	    // $$$TRACE("RETURNVALUE: " _ tOutParms.GetAt(1))
		for i=2:1:tOutParms.Count() 
		{   	
	       $$$TRACE(i _ "  OutParam: "_tOutParms.GetAt(i))	
	       ; add items to the list
			Do pResponse.outList.Insert(tOutParms.GetAt(i))			    	
		}

	}
	else
	{

		set errMsg = $System.Status.GetOneErrorText(tSC)
		$$$TRACE("ErrorText: " _ errMsg)

		if ($FIND(errMsg, "Duplicate") > 1)
		{
			set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).SkipMsgError("IHC.ITF.ITFCOMMON.Operation.OutTouchWorksStoredProc", errMsg)
		}

		set pResponse.RETURNVALUE = errMsg

		$$$TRACE("tRTs: " _ tRTs _ ",  $IsObject of tRTs : " _ $IsObject(tRTs))
		if ($IsObject(tRTs))
		{
			for i=1:1:tRTs.Count() 
			{   	
		       $$$TRACE(i _ "  tRTs: "_tRTs.GetAt(i))			    	
		       if (tRTs.GetAt(i).%IsA("EnsLib.SQL.Snapshot"))
		       {
			       $$$TRACE("%SQLCODE: " _ tRTs.GetAt(i).%SQLCODE _ ", %Message: " _ tRTs.GetAt(i).%Message _ ", " _ tRTs.GetAt(i).%ROWCOUNT)
		       }
			}
		}
		// When ever a call fails, the DB connection does not work for the next call to Stored proc
		// So disconnect to clean 
		Do ..Adapter.Disconnect()

	}
	$$$TRACE("Status: " _ tSC _ ", pResponse.RETURNVALUE: " _ pResponse.RETURNVALUE)	
	quit tSC
